nextflow_process {

    name "Test Process CYPSUBSTRATEPREDICTOR"
    script "../main.nf"
    process "CYPSUBSTRATEPREDICTOR"

    tag "modules"
    tag "cyp-substrate-predictor"

    test("cyp2d6 substrates - bundled weights") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file("\${projectDir}/modules/seqera/cyp-substrate-predictor/tests/molecules.csv", checkIfExists: true)
                ]
                input[1] = []
                """
            }
        }

        then {
            // Parse the CSV into id-keyed maps: assert on the science, not on row
            // order. A corrupt weights file would still emit a well-formed CSV.
            def lines = file(process.out.predictions[0][1]).readLines()
            def cols = lines[0].split(',') as List
            def rows = lines.drop(1)
                .collect { [cols, it.split(',', -1) as List].transpose().collectEntries() }
                .collectEntries { [(it.id): it] }

            assertAll(
                { assert process.success },
                { assert snapshot(process.out.predictions).match("predictions") },
                { assert snapshot(process.out.findAll { key, val -> key.startsWith('versions') }).match("versions") },
                // Classical CYP2D6 substrates must outrank the CYP2C9 drugs
                { assert rows['codeine'].p_substrate.toDouble() > 0.9 },
                { assert rows['dextromethorphan'].p_substrate.toDouble() > 0.8 },
                { assert rows['metoprolol'].p_substrate.toDouble() > 0.7 },
                { assert rows['ibuprofen'].p_substrate.toDouble() < 0.1 },
                { assert rows['aspirin'].p_substrate.toDouble() < 0.1 },
                // Unparsable input is flagged and left unscored, not given ~0.23
                { assert rows['unparsable'].valid == 'false' },
                { assert rows['unparsable'].p_substrate == '' }
            )
        }
    }

    test("cyp2d6 substrates - explicit pretrained_model") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file("\${projectDir}/modules/seqera/cyp-substrate-predictor/tests/molecules.csv", checkIfExists: true)
                ]
                input[1] = file("\${projectDir}/cyp_substrate/weights/cyp2d6_substrate_carbonmangels.npz", checkIfExists: true)
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out.predictions).match("predictions_explicit_model") }
            )
        }
    }

    test("cyp2d6 substrates - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file("\${projectDir}/modules/seqera/cyp-substrate-predictor/tests/molecules.csv", checkIfExists: true)
                ]
                input[1] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }
}
